   "html": "<section class=\"c-chart-slide\">\n  <div class=\"inner\">\n    <div class=\"head\">\n      <h2>Referrals now bring in more qualified leads than any paid channel</h2>\n      <p class=\"sub\">Qualified leads per quarter, by source, Q3 2026</p>\n    </div>\n    <div class=\"plot\">\n      <svg viewBox=\"0 0 860 250\" role=\"img\" aria-label=\"Bar chart of qualified leads in Q3 2026. Referrals 412, paid search 268, events 190, organic 175, outbound 96.\" preserveAspectRatio=\"xMidYMid meet\">\n        <g>\n          <line class=\"grid\" x1=\"64\" x2=\"860\" y1=\"146.7\" y2=\"146.7\"/>\n          <line class=\"grid\" x1=\"64\" x2=\"860\" y1=\"83.3\" y2=\"83.3\"/>\n          <line class=\"grid\" x1=\"64\" x2=\"860\" y1=\"20\" y2=\"20\"/>\n          <line class=\"base\" x1=\"64\" x2=\"860\" y1=\"210\" y2=\"210\"/>\n          <text class=\"tick\" x=\"54\" y=\"214\">0</text>\n          <text class=\"tick\" x=\"54\" y=\"151\">150</text>\n          <text class=\"tick\" x=\"54\" y=\"88\">300</text>\n          <text class=\"tick\" x=\"54\" y=\"25\">450</text>\n        </g>\n        <g>\n          <rect class=\"bar is-key\" x=\"104\" y=\"36\" width=\"90\" height=\"174\" rx=\"3\"/>\n          <rect class=\"bar\" x=\"262\" y=\"97\" width=\"90\" height=\"113\" rx=\"3\"/>\n          <rect class=\"bar\" x=\"420\" y=\"130\" width=\"90\" height=\"80\" rx=\"3\"/>\n          <rect class=\"bar\" x=\"578\" y=\"136\" width=\"90\" height=\"74\" rx=\"3\"/>\n          <rect class=\"bar\" x=\"736\" y=\"170\" width=\"90\" height=\"40\" rx=\"3\"/>\n        </g>\n        <g>\n          <text class=\"val is-key\" x=\"149\" y=\"27\">412</text>\n          <text class=\"val\" x=\"307\" y=\"88\">268</text>\n          <text class=\"val\" x=\"465\" y=\"121\">190</text>\n          <text class=\"val\" x=\"623\" y=\"127\">175</text>\n          <text class=\"val\" x=\"781\" y=\"161\">96</text>\n        </g>\n        <g>\n          <text class=\"cat is-key\" x=\"149\" y=\"236\">Referrals</text>\n          <text class=\"cat\" x=\"307\" y=\"236\">Paid search</text>\n          <text class=\"cat\" x=\"465\" y=\"236\">Events</text>\n          <text class=\"cat\" x=\"623\" y=\"236\">Organic</text>\n          <text class=\"cat\" x=\"781\" y=\"236\">Outbound</text>\n        </g>\n      </svg>\n    </div>\n    <div class=\"foot\">Source: CRM export, Q3 2026. Qualified means accepted by sales within seven days.</div>\n  </div>\n</section>",
   "css": ".c-chart-slide {\n  container-type: inline-size;\n  position: relative;\n  width: 100%;\n  aspect-ratio: 16 / 9;\n  overflow: hidden;\n  background: var(--ds-surface);\n  color: var(--ds-text);\n  font-family: var(--ds-font-sans);\n}\n.c-chart-slide .inner {\n  position: absolute;\n  inset: 0;\n  display: grid;\n  grid-template-rows: auto minmax(0, 1fr) auto;\n  row-gap: 1.6cqi;\n  padding: 5.5cqi 7cqi 4.5cqi;\n}\n.c-chart-slide .head { display: grid; gap: 1cqi; }\n.c-chart-slide h2 {\n  margin: 0;\n  max-width: 72cqi;\n  font-family: var(--ds-font-display);\n  font-size: 4cqi;\n  font-weight: var(--ds-weight-display);\n  letter-spacing: var(--ds-tracking-display);\n  line-height: 1.08;\n  color: var(--ds-ink);\n}\n.c-chart-slide .sub { margin: 0; font-size: 1.6cqi; color: var(--ds-muted); font-weight: 600; }\n.c-chart-slide .plot { min-height: 0; }\n.c-chart-slide svg { display: block; width: 100%; height: 100%; }\n.c-chart-slide .grid { stroke: var(--ds-line); stroke-width: 1; }\n.c-chart-slide .base { stroke: var(--ds-neutral-line); stroke-width: 1.5; }\n.c-chart-slide .tick { fill: var(--ds-muted); font-size: 13px; text-anchor: end; font-variant-numeric: tabular-nums; }\n.c-chart-slide .cat { fill: var(--ds-text); font-size: 15px; font-weight: 600; text-anchor: middle; }\n.c-chart-slide .val { fill: var(--ds-muted); font-size: 16px; font-weight: 700; text-anchor: middle; font-variant-numeric: tabular-nums; }\n.c-chart-slide .bar { fill: var(--ds-neutral-line); }\n.c-chart-slide .is-key.bar { fill: var(--ds-highlight-line); }\n.c-chart-slide .is-key.val { fill: var(--ds-ink); font-size: 20px; }\n.c-chart-slide .is-key.cat { fill: var(--ds-ink); font-weight: 800; }\n.c-chart-slide .foot { font-size: 1.3cqi; line-height: 1.4; color: var(--ds-muted); }",
