   "html": "<section class=\"c-comparison-slide\">\n  <div class=\"inner\">\n    <h2>Option B reaches the market fastest at the lowest risk</h2>\n    <div class=\"grid\">\n      <div class=\"head is-blank\"></div>\n      <div class=\"head\"><small>Option A</small>Build in-house</div>\n      <div class=\"head rec\"><span class=\"tag\">Recommended</span><small>Option B</small>Partner with a reseller</div>\n      <div class=\"head\"><small>Option C</small>Acquire a competitor</div>\n\n      <div class=\"crit\">Time to launch</div>\n      <div>6 months</div><div class=\"rec\">3 months</div><div>9 months</div>\n\n      <div class=\"crit\">Upfront cost</div>\n      <div>EUR 1.2m</div><div class=\"rec\">EUR 0.6m</div><div>EUR 2.1m</div>\n\n      <div class=\"crit\">Year-one revenue</div>\n      <div>EUR 3.4m</div><div class=\"rec\">EUR 2.8m</div><div>EUR 4.1m</div>\n\n      <div class=\"crit last\">Delivery risk</div>\n      <div class=\"risk last\"><i></i>Medium</div>\n      <div class=\"risk rec last\"><i class=\"low\"></i>Low</div>\n      <div class=\"risk last\"><i class=\"high\"></i>High</div>\n    </div>\n  </div>\n</section>",
   "css": ".c-comparison-slide {\n  container-type: inline-size;\n  position: relative;\n  width: 100%;\n  aspect-ratio: 16 / 9;\n  overflow: hidden;\n  background: var(--ds-surface);\n  color: var(--ds-text);\n  font-family: var(--ds-font-sans);\n}\n.c-comparison-slide .inner {\n  position: absolute;\n  inset: 0;\n  display: grid;\n  grid-template-rows: auto minmax(0, 1fr);\n  row-gap: 2.6cqi;\n  padding: 5.5cqi 7cqi 4.5cqi;\n}\n.c-comparison-slide h2 {\n  margin: 0;\n  max-width: 72cqi;\n  font-family: var(--ds-font-display);\n  font-size: 4cqi;\n  font-weight: var(--ds-weight-display);\n  letter-spacing: var(--ds-tracking-display);\n  line-height: 1.08;\n  color: var(--ds-ink);\n}\n.c-comparison-slide .grid {\n  display: grid;\n  grid-template-columns: 17cqi repeat(3, minmax(0, 1fr));\n  grid-template-rows: auto repeat(4, minmax(0, 1fr));\n  align-self: stretch;\n}\n.c-comparison-slide .grid > div {\n  display: flex;\n  align-items: center;\n  padding: 0 2.2cqi;\n  border-bottom: var(--ds-hairline) solid var(--ds-line);\n  font-size: 2cqi;\n  font-weight: 600;\n  color: var(--ds-ink);\n}\n.c-comparison-slide .grid > .crit {\n  padding-left: 0;\n  font-size: 1.6cqi;\n  font-weight: 600;\n  color: var(--ds-muted);\n}\n.c-comparison-slide .grid > .head {\n  display: grid;\n  align-content: end;\n  gap: 0.4cqi;\n  padding-top: 1.6cqi;\n  padding-bottom: 1.6cqi;\n  font-size: 2.1cqi;\n  font-weight: 800;\n  line-height: 1.2;\n}\n.c-comparison-slide .head small { font-size: 1.4cqi; font-weight: 600; color: var(--ds-muted); }\n.c-comparison-slide .head.is-blank { border-bottom-color: var(--ds-line); }\n\n.c-comparison-slide .grid > .rec {\n  background: var(--ds-highlight-fill);\n  border-left: var(--ds-stroke) solid var(--ds-highlight-line);\n  border-right: var(--ds-stroke) solid var(--ds-highlight-line);\n  border-bottom-color: color-mix(in srgb, var(--ds-highlight-line) 40%, transparent);\n}\n.c-comparison-slide .grid > .rec.head {\n  border-top: var(--ds-stroke) solid var(--ds-highlight-line);\n  border-radius: calc(1cqi * var(--ds-radius-scale, 1)) calc(1cqi * var(--ds-radius-scale, 1)) 0 0;\n}\n.c-comparison-slide .grid > .rec.last {\n  border-bottom: var(--ds-stroke) solid var(--ds-highlight-line);\n  border-radius: 0 0 calc(1cqi * var(--ds-radius-scale, 1)) calc(1cqi * var(--ds-radius-scale, 1));\n}\n.c-comparison-slide .grid > .last:not(.rec), .c-comparison-slide .grid > .crit.last { border-bottom-color: transparent; }\n.c-comparison-slide .tag {\n  justify-self: start;\n  padding: 0.35cqi 1cqi;\n  border-radius: 99px;\n  background: var(--ds-highlight-line);\n  font-size: 1.2cqi;\n  font-weight: 800;\n  letter-spacing: 0.02em;\n  color: var(--ds-bg);\n}\n.c-comparison-slide .risk { gap: 1cqi; }\n.c-comparison-slide .risk i { width: 1.2cqi; height: 1.2cqi; border-radius: 50%; background: var(--ds-neutral-line); flex: none; }\n.c-comparison-slide .risk .low { background: var(--ds-note-line); }\n.c-comparison-slide .risk .high { background: var(--ds-danger-line); }",
