   "html": "<section class=\"c-title-slide\">\n  <div class=\"mark\" aria-hidden=\"true\"></div>\n  <div class=\"inner\">\n    <div class=\"eyebrow\">Strategy review, Q4</div>\n    <div class=\"main\">\n      <h1>Where the next twelve months of growth come from</h1>\n      <p class=\"sub\">Three bets, what they cost, and the one decision we need from this room today.</p>\n    </div>\n    <div class=\"foot\"><span><b>Presenter Name</b>, Company</span><span>31 October 2026</span></div>\n  </div>\n</section>",
   "css": ".c-title-slide {\n  container-type: inline-size;\n  position: relative;\n  width: 100%;\n  aspect-ratio: 16 / 9;\n  overflow: hidden;\n  background: var(--ds-surface);\n  color: var(--ds-text);\n  font-family: var(--ds-font-sans);\n}\n.c-title-slide .inner {\n  position: absolute;\n  inset: 0;\n  display: grid;\n  grid-template-rows: auto 1fr auto;\n  padding: 6cqi 7cqi;\n}\n.c-title-slide .eyebrow { font-size: 1.5cqi; font-weight: 600; color: var(--ds-muted); }\n.c-title-slide .main { align-self: center; display: grid; gap: 2.2cqi; max-width: 70cqi; }\n.c-title-slide h1 {\n  margin: 0;\n  font-family: var(--ds-font-display);\n  font-size: 6.4cqi;\n  font-weight: var(--ds-weight-display);\n  letter-spacing: var(--ds-tracking-display);\n  line-height: 1.02;\n  color: var(--ds-ink);\n}\n.c-title-slide .sub { font-size: 2cqi; line-height: 1.45; max-width: 52cqi; }\n.c-title-slide .foot {\n  display: flex;\n  justify-content: space-between;\n  align-items: end;\n  padding-top: 2cqi;\n  border-top: var(--ds-hairline) solid var(--ds-line);\n  font-size: 1.3cqi;\n  color: var(--ds-muted);\n}\n.c-title-slide .foot b { color: var(--ds-text); font-weight: 600; }\n.c-title-slide .mark {\n  position: absolute;\n  right: 7cqi;\n  top: 6cqi;\n  width: 3.2cqi;\n  height: 3.2cqi;\n  border-radius: calc(0.6cqi * var(--ds-radius-scale, 1));\n  background: var(--ds-highlight-line);\n}",
