   "html": "<div class=\"c-copy-field\">\n  <label class=\"label\" for=\"c-copy-field-input\">Invite link</label>\n  <div class=\"field\">\n    <input class=\"input\" id=\"c-copy-field-input\" type=\"text\" readonly value=\"https://app.stackwell.example/invite/k7x2-91fm-q4tz\">\n    <button class=\"copy\" type=\"button\" aria-label=\"Copy invite link\">\n      <span class=\"idle\"><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"5.5\" y=\"5.5\" width=\"8\" height=\"8\" rx=\"1.5\"/><path d=\"M10.5 5.5V4A1.5 1.5 0 0 0 9 2.5H4A1.5 1.5 0 0 0 2.5 4v5A1.5 1.5 0 0 0 4 10.5h1.5\"/></svg>Copy</span>\n      <span class=\"done\"><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3.5 8.5l3 3 6-7\"/></svg>Copied</span>\n    </button>\n  </div>\n  <p class=\"help\" role=\"status\" aria-live=\"polite\">Anyone with this link can join as a reviewer for 7 days.</p>\n</div>",
   "css": ".c-copy-field {\n  display: grid;\n  gap: var(--ds-space-2);\n  width: min(480px, 100%);\n  font-family: var(--ds-font-sans);\n  color: var(--ds-text);\n}\n.c-copy-field .label { font-size: var(--ds-text-sm); font-weight: 600; color: var(--ds-ink); }\n.c-copy-field .field {\n  display: flex;\n  align-items: center;\n  gap: var(--ds-space-2);\n  padding: var(--ds-space-1) var(--ds-space-1) var(--ds-space-1) var(--ds-space-4);\n  border: var(--ds-stroke) solid var(--ds-line);\n  border-radius: var(--ds-radius-pill);\n  background: var(--ds-surface);\n  transition: border-color var(--ds-dur-fast) var(--ds-ease), box-shadow var(--ds-dur-fast) var(--ds-ease);\n}\n.c-copy-field .field:focus-within { border-color: var(--ds-info-line); box-shadow: var(--ds-focus); }\n.c-copy-field .input {\n  flex: 1;\n  min-width: 0;\n  height: 40px;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: var(--ds-ink);\n  font-family: var(--ds-font-mono);\n  font-size: var(--ds-text-sm);\n  text-overflow: ellipsis;\n  outline: none;\n}\n.c-copy-field .input:focus-visible { box-shadow: none; }\n.c-copy-field .copy {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: var(--ds-space-2);\n  flex: none;\n  min-width: 104px;\n  height: 40px;\n  padding: 0 var(--ds-space-4);\n  border: var(--ds-stroke) solid transparent;\n  border-radius: var(--ds-radius-pill);\n  background: var(--ds-action);\n  color: var(--ds-on-action);\n  font-size: var(--ds-text-sm);\n  font-weight: 600;\n  cursor: pointer;\n  transition: background var(--ds-dur-base) var(--ds-ease), color var(--ds-dur-base) var(--ds-ease), border-color var(--ds-dur-base) var(--ds-ease);\n}\n.c-copy-field .copy:hover { background: color-mix(in srgb, var(--ds-action) 86%, var(--ds-on-action)); }\n.c-copy-field .copy:focus-visible { outline: none; box-shadow: var(--ds-focus); }\n.c-copy-field .copy svg { width: 16px; height: 16px; }\n.c-copy-field .copy .done { display: none; }\n.c-copy-field .copy.is-copied { background: var(--ds-note-fill); border-color: var(--ds-note-line); color: var(--ds-ink); }\n.c-copy-field .copy.is-copied .idle { display: none; }\n.c-copy-field .copy.is-copied .done { display: inline-flex; align-items: center; gap: var(--ds-space-2); animation: c-copy-field-pop var(--ds-dur-base) var(--ds-ease-spring); }\n@keyframes c-copy-field-pop { from { opacity: 0; transform: scale(0.85); } to { opacity: 1; transform: none; } }\n.c-copy-field .copy .idle { display: inline-flex; align-items: center; gap: var(--ds-space-2); }\n.c-copy-field .help { font-size: var(--ds-text-xs); color: var(--ds-muted); }",
   "js": "(() => {\n  document.querySelectorAll('.c-copy-field').forEach((root, n) => {\n    const input = root.querySelector('.input');\n    const label = root.querySelector('.label');\n    const btn = root.querySelector('.copy');\n    const help = root.querySelector('.help');\n    const original = help.textContent;\n    input.id = `c-copy-field-input-${n}`;\n    label.setAttribute('for', input.id);\n    let timer;\n\n    const fallback = (text) => {\n      input.focus();\n      input.select();\n      input.setSelectionRange(0, text.length);\n      try { return document.execCommand('copy'); } catch (e) { return false; }\n    };\n    const copy = async (text) => {\n      if (navigator.clipboard && window.isSecureContext) {\n        try { await navigator.clipboard.writeText(text); return true; } catch (e) { /* fall through */ }\n      }\n      return fallback(text);\n    };\n\n    btn.addEventListener('click', async () => {\n      const ok = await copy(input.value);\n      clearTimeout(timer);\n      btn.classList.toggle('is-copied', ok);\n      help.textContent = ok ? 'Link copied to your clipboard.' : 'Press Ctrl or Cmd C to copy the selected link.';\n      timer = setTimeout(() => { btn.classList.remove('is-copied'); help.textContent = original; }, 2000);\n    });\n    // selecting the whole value on focus makes manual copying one keystroke\n    input.addEventListener('focus', () => input.select());\n  });\n})();"
