   "html": "<div class=\"c-stagger-cards\">\n  <article class=\"card\" style=\"--i: 0\"><span class=\"num\">01</span><h3 class=\"title\">Discovery</h3><p class=\"text\">Interviews and a data review to find the real constraint.</p></article>\n  <article class=\"card\" style=\"--i: 1\"><span class=\"num\">02</span><h3 class=\"title\">Positioning</h3><p class=\"text\">One sentence the whole team can repeat without notes.</p></article>\n  <article class=\"card\" style=\"--i: 2\"><span class=\"num\">03</span><h3 class=\"title\">Design system</h3><p class=\"text\">Tokens and components that make the next page fast.</p></article>\n  <article class=\"card\" style=\"--i: 3\"><span class=\"num\">04</span><h3 class=\"title\">Build</h3><p class=\"text\">Thin slices shipped weekly, each one testable on its own.</p></article>\n  <article class=\"card\" style=\"--i: 4\"><span class=\"num\">05</span><h3 class=\"title\">Launch</h3><p class=\"text\">Tracking, redirects and a rollback plan before go-live.</p></article>\n  <article class=\"card\" style=\"--i: 5\"><span class=\"num\">06</span><h3 class=\"title\">Handover</h3><p class=\"text\">Documentation and a recorded walkthrough for your team.</p></article>\n</div>",
   "css": ".c-stagger-cards,\n.c-stagger-cards *,\n.c-stagger-cards *::before,\n.c-stagger-cards *::after { box-sizing: border-box; }\n.c-stagger-cards {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: var(--ds-space-4);\n  max-width: 960px;\n  margin-inline: auto;\n  padding: var(--ds-space-7);\n  font-family: var(--ds-font-sans);\n  color: var(--ds-text);\n}\n.c-stagger-cards .card {\n  display: grid;\n  align-content: start;\n  gap: var(--ds-space-3);\n  padding: var(--ds-space-5);\n  background: var(--ds-surface);\n  border: var(--ds-hairline) solid var(--ds-line);\n  border-radius: var(--ds-radius-lg);\n}\n.c-stagger-cards .num { font-size: var(--ds-text-sm); font-weight: 700; color: var(--ds-muted); font-variant-numeric: tabular-nums; }\n.c-stagger-cards .title { margin: 0; font-size: var(--ds-text-lg); font-weight: 700; line-height: var(--ds-leading-snug); color: var(--ds-ink); }\n.c-stagger-cards .text { margin: 0; font-size: var(--ds-text-sm); line-height: var(--ds-leading-body); }\n@media (max-width: 760px) {\n  .c-stagger-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); padding: var(--ds-space-5); }\n}\n@media (max-width: 480px) {\n  .c-stagger-cards { grid-template-columns: 1fr; }\n}\n\n/* the hidden state carries no transition, so arming never animates; only the move to .is-in does */\n.c-stagger-cards.is-armed .card { opacity: 0; transform: translateY(20px) scale(0.96); }\n.c-stagger-cards.is-armed.is-in .card {\n  opacity: 1;\n  transform: none;\n  transition: opacity var(--ds-dur-slow) var(--ds-ease), transform var(--ds-dur-slow) var(--ds-ease);\n  transition-delay: calc(var(--i) * 90ms);\n}",
   "js": "(() => {\n  const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  document.querySelectorAll('.c-stagger-cards').forEach((root) => {\n    if (reduced) return;\n    root.classList.add('is-armed');\n    const io = new IntersectionObserver((entries) => {\n      if (!entries.some((e) => e.isIntersecting)) return;\n      io.disconnect();\n      requestAnimationFrame(() => requestAnimationFrame(() => root.classList.add('is-in')));\n    }, { threshold: 0.3 });\n    io.observe(root);\n  });\n})();"
