   "html": "<section class=\"c-cta-band\">\n  <div class=\"band\">\n    <svg class=\"rings\" viewBox=\"0 0 800 300\" preserveAspectRatio=\"xMidYMid slice\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" aria-hidden=\"true\">\n      <circle cx=\"120\" cy=\"300\" r=\"120\"/><circle cx=\"120\" cy=\"300\" r=\"200\"/><circle cx=\"120\" cy=\"300\" r=\"280\"/>\n      <circle cx=\"700\" cy=\"0\" r=\"120\"/><circle cx=\"700\" cy=\"0\" r=\"200\"/><circle cx=\"700\" cy=\"0\" r=\"280\"/>\n    </svg>\n    <div class=\"inner\">\n      <h2>Make next month's close the calm one</h2>\n      <p class=\"sub\">Start a 14 day trial with your own data. Most teams are reconciling their first account the same afternoon.</p>\n      <div class=\"actions\">\n        <a class=\"btn btn--inverse\" href=\"#\">Start free trial</a>\n        <a class=\"btn btn--ghost\" href=\"#\">Talk to sales</a>\n      </div>\n      <p class=\"fine\">No credit card needed. Cancel any time.</p>\n    </div>\n  </div>\n</section>",
   "css": ".c-cta-band {\n  background: var(--ds-bg);\n  padding: var(--ds-space-9) var(--ds-space-6);\n  font-family: var(--ds-font-sans);\n}\n.c-cta-band .band {\n  position: relative;\n  max-width: 1120px;\n  margin: 0 auto;\n  padding: var(--ds-space-9) var(--ds-space-7);\n  border-radius: var(--ds-radius-xl);\n  background: var(--ds-action);\n  color: var(--ds-on-action);\n  text-align: center;\n  overflow: hidden;\n}\n.c-cta-band .rings {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  color: var(--ds-on-action);\n  opacity: 0.1;\n  pointer-events: none;\n}\n.c-cta-band .inner { position: relative; display: grid; gap: var(--ds-space-4); justify-items: center; }\n.c-cta-band h2 {\n  max-width: 16em;\n  margin: 0;\n  font-family: var(--ds-font-display);\n  font-size: var(--ds-text-2xl);\n  font-weight: var(--ds-weight-display);\n  letter-spacing: var(--ds-tracking-display);\n  line-height: var(--ds-leading-tight);\n  color: var(--ds-on-action);\n  text-wrap: balance;\n}\n.c-cta-band .sub { max-width: 34em; font-size: var(--ds-text-lg); line-height: var(--ds-leading-snug); color: color-mix(in srgb, var(--ds-on-action) 78%, transparent); text-wrap: pretty; }\n.c-cta-band .actions { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: var(--ds-space-3); margin-top: var(--ds-space-4); }\n.c-cta-band .btn {\n  display: inline-flex;\n  align-items: center;\n  height: 48px;\n  padding: 0 var(--ds-space-6);\n  border: var(--ds-stroke) solid transparent;\n  border-radius: var(--ds-radius-pill);\n  font-size: var(--ds-text-md);\n  font-weight: 600;\n  text-decoration: none;\n  transition: background var(--ds-dur-fast) var(--ds-ease);\n}\n.c-cta-band .btn:focus-visible { outline: none; box-shadow: 0 0 0 3px color-mix(in srgb, var(--ds-on-action) 55%, transparent); }\n.c-cta-band .btn--inverse { background: var(--ds-on-action); color: var(--ds-action); }\n.c-cta-band .btn--inverse:hover { background: color-mix(in srgb, var(--ds-on-action) 88%, var(--ds-action)); }\n.c-cta-band .btn--ghost { color: var(--ds-on-action); border-color: color-mix(in srgb, var(--ds-on-action) 35%, transparent); }\n.c-cta-band .btn--ghost:hover { background: color-mix(in srgb, var(--ds-on-action) 10%, transparent); }\n.c-cta-band .fine { font-size: var(--ds-text-sm); color: color-mix(in srgb, var(--ds-on-action) 62%, transparent); }\n@media (max-width: 600px) {\n  .c-cta-band { padding: var(--ds-space-7) var(--ds-space-4); }\n  .c-cta-band .band { padding: var(--ds-space-8) var(--ds-space-5); }\n  .c-cta-band h2 { font-size: var(--ds-text-xl); }\n  .c-cta-band .sub { font-size: var(--ds-text-md); }\n  .c-cta-band .btn { flex: 1 1 100%; justify-content: center; }\n}",
