   "html": "<footer class=\"c-footer\">\n  <div class=\"wrap\">\n    <div class=\"top\">\n      <div class=\"brand-col\">\n        <a class=\"brand\" href=\"#\">\n          <svg viewBox=\"0 0 28 28\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"3\" width=\"22\" height=\"22\" rx=\"6\"/><path d=\"M9 17l4-4 3 3 4-5\"/></svg>\n          Stackwell\n        </a>\n        <p class=\"blurb\">Month-end close software for finance teams that would rather be analysing than chasing.</p>\n        <a class=\"status\" href=\"#\"><i aria-hidden=\"true\"></i>All systems normal</a>\n      </div>\n      <nav aria-label=\"Product\">\n        <h2>Product</h2>\n        <ul>\n          <li><a class=\"link\" href=\"#\">Reconciliation</a></li>\n          <li><a class=\"link\" href=\"#\">Close checklist</a></li>\n          <li><a class=\"link\" href=\"#\">Variance notes</a></li>\n          <li><a class=\"link\" href=\"#\">Integrations</a></li>\n          <li><a class=\"link\" href=\"#\">Pricing</a></li>\n        </ul>\n      </nav>\n      <nav aria-label=\"Company\">\n        <h2>Company</h2>\n        <ul>\n          <li><a class=\"link\" href=\"#\">About</a></li>\n          <li><a class=\"link\" href=\"#\">Customers</a></li>\n          <li><a class=\"link\" href=\"#\">Careers</a></li>\n          <li><a class=\"link\" href=\"#\">Press</a></li>\n          <li><a class=\"link\" href=\"#\">Contact</a></li>\n        </ul>\n      </nav>\n      <nav aria-label=\"Resources\">\n        <h2>Resources</h2>\n        <ul>\n          <li><a class=\"link\" href=\"#\">Documentation</a></li>\n          <li><a class=\"link\" href=\"#\">Close guides</a></li>\n          <li><a class=\"link\" href=\"#\">API reference</a></li>\n          <li><a class=\"link\" href=\"#\">Changelog</a></li>\n        </ul>\n      </nav>\n      <nav aria-label=\"Security\">\n        <h2>Security</h2>\n        <ul>\n          <li><a class=\"link\" href=\"#\">Trust centre</a></li>\n          <li><a class=\"link\" href=\"#\">Data processing</a></li>\n          <li><a class=\"link\" href=\"#\">Subprocessors</a></li>\n          <li><a class=\"link\" href=\"#\">Report an issue</a></li>\n        </ul>\n      </nav>\n    </div>\n    <div class=\"small\">\n      <span>&copy; 2026 Stackwell, Inc. All rights reserved.</span>\n      <ul>\n        <li><a class=\"link\" href=\"#\">Privacy</a></li>\n        <li><a class=\"link\" href=\"#\">Terms</a></li>\n        <li><a class=\"link\" href=\"#\">Cookies</a></li>\n        <li><a class=\"link\" href=\"#\">Accessibility</a></li>\n      </ul>\n    </div>\n  </div>\n</footer>",
   "css": ".c-footer {\n  background: var(--ds-surface);\n  border-top: var(--ds-hairline) solid var(--ds-line);\n  font-family: var(--ds-font-sans);\n  color: var(--ds-text);\n}\n.c-footer .wrap { max-width: 1200px; margin: 0 auto; padding: var(--ds-space-9) var(--ds-space-6) var(--ds-space-6); }\n.c-footer .top { display: grid; grid-template-columns: minmax(0, 5fr) repeat(4, minmax(0, 2fr)); gap: var(--ds-space-7); }\n.c-footer .brand-col { display: grid; align-content: start; gap: var(--ds-space-4); max-width: 320px; }\n.c-footer .brand { display: inline-flex; align-items: center; gap: var(--ds-space-3); width: fit-content; border-radius: var(--ds-radius-sm); color: var(--ds-ink); font-size: var(--ds-text-lg); font-weight: 800; letter-spacing: -0.02em; text-decoration: none; }\n.c-footer .brand svg { width: 28px; height: 28px; }\n.c-footer .blurb { font-size: var(--ds-text-sm); line-height: var(--ds-leading-body); }\n.c-footer .status { display: inline-flex; align-items: center; gap: var(--ds-space-2); width: fit-content; padding: var(--ds-space-1) var(--ds-space-3); border: var(--ds-hairline) solid var(--ds-note-line); border-radius: var(--ds-radius-pill); background: var(--ds-note-fill); color: var(--ds-ink); font-size: var(--ds-text-xs); font-weight: 600; text-decoration: none; }\n.c-footer .status i { width: 8px; height: 8px; border-radius: var(--ds-radius-pill); background: var(--ds-note-line); }\n.c-footer h2 { margin: 0 0 var(--ds-space-4); font-size: var(--ds-text-sm); font-weight: 700; color: var(--ds-ink); }\n.c-footer ul { display: grid; gap: var(--ds-space-3); margin: 0; padding: 0; list-style: none; }\n.c-footer a.link { border-radius: var(--ds-radius-sm); color: var(--ds-text); font-size: var(--ds-text-sm); text-decoration: none; transition: color var(--ds-dur-fast) var(--ds-ease); }\n.c-footer a.link:hover { color: var(--ds-ink); text-decoration: underline; text-underline-offset: 3px; }\n.c-footer a:focus-visible { outline: none; box-shadow: var(--ds-focus); }\n.c-footer .small { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--ds-space-3) var(--ds-space-6); margin-top: var(--ds-space-8); padding-top: var(--ds-space-5); border-top: var(--ds-hairline) solid var(--ds-line); font-size: var(--ds-text-xs); color: var(--ds-muted); }\n.c-footer .small ul { display: flex; flex-wrap: wrap; gap: var(--ds-space-2) var(--ds-space-5); }\n.c-footer .small a.link { font-size: var(--ds-text-xs); color: var(--ds-muted); }\n@media (max-width: 960px) {\n  .c-footer .top { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--ds-space-7) var(--ds-space-5); }\n  .c-footer .brand-col { grid-column: 1 / -1; max-width: 420px; }\n}\n@media (max-width: 600px) {\n  .c-footer .wrap { padding: var(--ds-space-8) var(--ds-space-4) var(--ds-space-5); }\n  .c-footer .top { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--ds-space-7) var(--ds-space-5); }\n  .c-footer .small { flex-direction: column; align-items: flex-start; }\n}",
