   "html": "<section class=\"c-stat-strip\" aria-label=\"Headline numbers, Q3 2026\">\n  <ul class=\"items\">\n    <li class=\"item\">\n      <p class=\"label\">Net revenue</p>\n      <p class=\"value\">€2.84M</p>\n      <p class=\"meta\">\n        <span class=\"chip is-up is-good\"><svg viewBox=\"0 0 10 10\" aria-hidden=\"true\"><path d=\"M5 1.5 9.5 8.5H.5z\"/></svg>12.4%<span class=\"sr\"> up, favourable</span></span>\n        <span class=\"vs\">vs Q2</span>\n      </p>\n    </li>\n    <li class=\"item\">\n      <p class=\"label\">Active customers</p>\n      <p class=\"value\">1,486</p>\n      <p class=\"meta\">\n        <span class=\"chip is-up is-good\"><svg viewBox=\"0 0 10 10\" aria-hidden=\"true\"><path d=\"M5 1.5 9.5 8.5H.5z\"/></svg>6.1%<span class=\"sr\"> up, favourable</span></span>\n        <span class=\"vs\">vs Q2</span>\n      </p>\n    </li>\n    <li class=\"item\">\n      <p class=\"label\">Gross margin</p>\n      <p class=\"value\">61.2%</p>\n      <p class=\"meta\">\n        <span class=\"chip is-down is-bad\"><svg viewBox=\"0 0 10 10\" aria-hidden=\"true\"><path d=\"M5 1.5 9.5 8.5H.5z\"/></svg>1.8 pts<span class=\"sr\"> down, unfavourable</span></span>\n        <span class=\"vs\">vs Q2</span>\n      </p>\n    </li>\n    <li class=\"item\">\n      <p class=\"label\">Open support tickets</p>\n      <p class=\"value\">142</p>\n      <p class=\"meta\">\n        <span class=\"chip is-down is-good\"><svg viewBox=\"0 0 10 10\" aria-hidden=\"true\"><path d=\"M5 1.5 9.5 8.5H.5z\"/></svg>18%<span class=\"sr\"> down, favourable</span></span>\n        <span class=\"vs\">vs Q2</span>\n      </p>\n    </li>\n  </ul>\n</section>",
   "css": ".c-stat-strip {\n  padding: var(--ds-space-7) var(--ds-space-6);\n  background: var(--ds-surface);\n  border-radius: var(--ds-radius-xl);\n  font-family: var(--ds-font-sans);\n  color: var(--ds-text);\n}\n.c-stat-strip .sr {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  white-space: nowrap;\n}\n.c-stat-strip .items {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n.c-stat-strip .item {\n  display: grid;\n  align-content: start;\n  gap: var(--ds-space-3);\n  padding: 0 var(--ds-space-5);\n}\n.c-stat-strip .item + .item { border-left: var(--ds-hairline) solid var(--ds-line); }\n.c-stat-strip .item:first-child { padding-left: 0; }\n.c-stat-strip .label { margin: 0; color: var(--ds-muted); font-size: var(--ds-text-sm); font-weight: 600; }\n.c-stat-strip .value {\n  margin: 0;\n  font-family: var(--ds-font-display);\n  font-size: var(--ds-text-2xl);\n  font-weight: var(--ds-weight-display);\n  letter-spacing: var(--ds-tracking-display);\n  line-height: 1;\n  color: var(--ds-ink);\n  font-variant-numeric: tabular-nums;\n}\n.c-stat-strip .meta { display: flex; flex-wrap: wrap; align-items: center; gap: var(--ds-space-2); margin: 0; }\n.c-stat-strip .chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  padding: 3px 9px 3px 7px;\n  border: var(--ds-hairline) solid;\n  border-radius: var(--ds-radius-pill);\n  font-size: var(--ds-text-xs);\n  font-weight: 700;\n  line-height: 1.2;\n  color: var(--ds-ink);\n  font-variant-numeric: tabular-nums;\n}\n.c-stat-strip .chip svg { width: 9px; height: 9px; fill: currentColor; }\n.c-stat-strip .chip.is-down svg { transform: rotate(180deg); }\n.c-stat-strip .chip.is-good { background: var(--ds-note-fill); border-color: var(--ds-note-line); }\n.c-stat-strip .chip.is-bad { background: var(--ds-danger-fill); border-color: var(--ds-danger-line); }\n.c-stat-strip .vs { color: var(--ds-muted); font-size: var(--ds-text-xs); }\n@media (max-width: 720px) {\n  .c-stat-strip { padding: var(--ds-space-6) var(--ds-space-5); }\n  .c-stat-strip .items { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: var(--ds-space-6); }\n  .c-stat-strip .item { padding: 0 0 0 var(--ds-space-5); }\n  .c-stat-strip .item:nth-child(odd) { padding-left: 0; border-left: 0; }\n  .c-stat-strip .value { font-size: var(--ds-text-xl); }\n}",
